import { Icons } from '../../ui/icons.ts';
import { SurvivorEngine } from './SurvivorEngine.ts';
import { getSurvivorSvg } from './data/icons.ts';

export class SurvivorView {
  private container: HTMLElement;
  private engine: SurvivorEngine | null = null;
  private cleanups: (() => void)[] = [];

  constructor(container: HTMLElement) {
    this.container = container;
  }

  public mount(): () => void {
    this.container.innerHTML = `
      <div class="game-view survivor-view">
        <!-- Top HUD -->
        <header class="arcade-header">
          <div class="brand-section">
            <button id="btn-back-lobby" class="icon-btn back-btn" title="返回大廳" aria-label="返回大廳">
              ${Icons.back}
            </button>
            <span class="brand-title">SURVIVOR</span>
          </div>

          <div class="survivor-hud-center">
            <div class="bar-row">
              <span class="bar-tag hp-tag">HP</span>
              <div class="progress-track hp-track">
                <div id="hp-bar-fill" class="progress-fill hp-fill" style="width: 100%;"></div>
              </div>
            </div>
            <div class="bar-row">
              <span id="level-badge" class="bar-tag exp-tag">LV.1</span>
              <div class="progress-track exp-track">
                <div id="exp-bar-fill" class="progress-fill exp-fill" style="width: 0%;"></div>
              </div>
            </div>
          </div>

          <div class="hud-stats">
            <div class="stat-item">
              <span class="stat-label">KILLS</span>
              <span id="stat-kills" class="stat-value score">0</span>
            </div>
            <div class="stat-item">
              <span class="stat-label">TIME</span>
              <span id="stat-time" class="stat-value">0:00</span>
            </div>
          </div>

          <div class="hud-actions">
            <button id="btn-audio" class="icon-btn" title="切換音效" aria-label="切換音效">
              ${Icons.volume}
            </button>
          </div>
        </header>

        <!-- Canvas Arena Container -->
        <main class="canvas-container">
          <div class="canvas-wrapper survivor-wrapper">
            <canvas id="survivor-canvas"></canvas>

            <!-- Macro Event Breaking News Ticker -->
            <div id="macro-event-banner" class="macro-event-banner" style="display: none;"></div>

            <!-- Level Up Selection Modal -->
            <div id="levelup-modal" class="modal-overlay">
              <div class="game-modal upgrade-modal">
                <span class="upgrade-header-pill">LEVEL UP!</span>
                <h3 class="upgrade-modal-title">CHOOSE TALENT</h3>
                <div id="upgrade-cards-list" class="upgrade-cards-list"></div>
              </div>
            </div>

            <!-- Game Over Modal -->
            <div id="gameover-modal" class="modal-overlay">
              <div class="game-modal">
                <h2 class="modal-title">DEFEATED</h2>
                <div class="modal-stats-grid">
                  <div class="modal-stat-box">
                    <span class="modal-stat-label">擊殺數量</span>
                    <span id="modal-kills" class="modal-stat-val primary">0</span>
                  </div>
                  <div class="modal-stat-box">
                    <span class="modal-stat-label">生存時間</span>
                    <span id="modal-time" class="modal-stat-val">0:00</span>
                  </div>
                  <div class="modal-stat-box" style="grid-column: span 2;">
                    <span class="modal-stat-label">最終等級</span>
                    <span id="modal-level" class="modal-stat-val" style="color: var(--gold-color);">LV. 1</span>
                  </div>
                </div>

                <div class="modal-actions">
                  <button id="btn-restart" class="btn-primary">
                    ${Icons.restart}
                    <span>PLAY AGAIN</span>
                  </button>
                  <div class="share-row">
                    <button id="btn-share-x" class="btn-secondary">
                      ${Icons.xLogo}
                      <span>SHARE TO X</span>
                    </button>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </main>

        <!-- Touch Virtual Joystick Area -->
        <nav id="survivor-touch-zone" class="survivor-joystick-zone" aria-label="Touch Joystick">
          <div id="joystick-base" class="joystick-base">
            <div id="joystick-stick" class="joystick-stick"></div>
          </div>
          <span class="joystick-hint">TOUCH AND DRAG TO MOVE</span>
        </nav>
      </div>
    `;

    // Elements
    const canvas = this.container.querySelector('#survivor-canvas') as HTMLCanvasElement;
    const canvasWrapper = this.container.querySelector('.canvas-wrapper') as HTMLElement;
    const btnBack = this.container.querySelector('#btn-back-lobby') as HTMLButtonElement;
    const hpFill = this.container.querySelector('#hp-bar-fill') as HTMLElement;
    const expFill = this.container.querySelector('#exp-bar-fill') as HTMLElement;
    const levelBadge = this.container.querySelector('#level-badge') as HTMLElement;
    const statKills = this.container.querySelector('#stat-kills') as HTMLElement;
    const statTime = this.container.querySelector('#stat-time') as HTMLElement;
    const btnAudio = this.container.querySelector('#btn-audio') as HTMLButtonElement;

    const levelupModal = this.container.querySelector('#levelup-modal') as HTMLElement;
    const upgradeCardsList = this.container.querySelector('#upgrade-cards-list') as HTMLElement;
    const gameoverModal = this.container.querySelector('#gameover-modal') as HTMLElement;
    const modalKills = this.container.querySelector('#modal-kills') as HTMLElement;
    const modalTime = this.container.querySelector('#modal-time') as HTMLElement;
    const modalLevel = this.container.querySelector('#modal-level') as HTMLElement;
    const btnRestart = this.container.querySelector('#btn-restart') as HTMLButtonElement;
    const btnShareX = this.container.querySelector('#btn-share-x') as HTMLButtonElement;

    const touchZone = this.container.querySelector('#survivor-touch-zone') as HTMLElement;
    const joystickBase = this.container.querySelector('#joystick-base') as HTMLElement;
    const joystickStick = this.container.querySelector('#joystick-stick') as HTMLElement;
    const macroEventBanner = this.container.querySelector('#macro-event-banner') as HTMLElement;

    // Back to Lobby
    btnBack.addEventListener('click', () => {
      window.location.hash = '#/';
    });

    let currentKills = 0;
    let currentTimeSec = 0;
    let currentLevel = 1;

    let lastMacroEventId: string | null = null;
    let lastRemainingSec = -1;

    // Initialize Engine
    this.engine = new SurvivorEngine(canvas, {
      onHpChange: (hp, maxHp) => {
        const pct = Math.max(0, Math.min(100, (hp / maxHp) * 100));
        hpFill.style.width = `${pct}%`;
      },
      onExpChange: (exp, nextExp, level) => {
        const pct = Math.max(0, Math.min(100, (exp / nextExp) * 100));
        expFill.style.width = `${pct}%`;
        levelBadge.textContent = `LV.${level}`;
      },
      onKillsChange: (kills) => {
        currentKills = kills;
        statKills.textContent = kills.toString();
      },
      onTimerChange: (seconds) => {
        currentTimeSec = seconds;
        const mins = Math.floor(seconds / 60);
        const secs = seconds % 60;
        statTime.textContent = `${mins}:${secs < 10 ? '0' : ''}${secs}`;
      },
      onMacroEvent: (event, remainingSec) => {
        if (!event || remainingSec <= 0) {
          if (lastMacroEventId !== null) {
            macroEventBanner.style.display = 'none';
            macroEventBanner.classList.remove('active');
            lastMacroEventId = null;
            lastRemainingSec = -1;
          }
          return;
        }

        if (lastMacroEventId !== event.id) {
          lastMacroEventId = event.id;
          lastRemainingSec = remainingSec;
          macroEventBanner.style.display = 'flex';
          macroEventBanner.classList.add('active');
          macroEventBanner.style.background = event.bannerBg;
          macroEventBanner.style.borderColor = event.borderColor;
          macroEventBanner.style.boxShadow = `0 4px 20px ${event.glowColor}`;
          macroEventBanner.innerHTML = `
            <div class="macro-banner-icon">${getSurvivorSvg(event.iconKey, 24, '#ffffff')}</div>
            <div class="macro-banner-content">
              <div class="macro-banner-row">
                <span class="macro-pill">${event.badge}</span>
                <span class="macro-name">${event.name}</span>
                <span id="macro-timer-val" class="macro-timer-pill">${remainingSec}s</span>
              </div>
              <div class="macro-headline">${event.headline}</div>
            </div>
          `;
        } else if (lastRemainingSec !== remainingSec) {
          lastRemainingSec = remainingSec;
          const timerEl = macroEventBanner.querySelector('#macro-timer-val');
          if (timerEl) {
            timerEl.textContent = `${remainingSec}s`;
          }
        }
      },
      onLevelUp: (choices) => {
        if (this.engine) {
          this.engine.setMoveVector(0, 0);
        }
        upgradeCardsList.innerHTML = choices
          .map(
            (c) => `
          <button class="upgrade-card-btn" data-id="${c.id}">
            <div class="upgrade-card-icon-col">
              ${getSurvivorSvg(c.iconKey, 24, '#00e676')}
            </div>
            <div class="upgrade-card-info">
              <div class="upgrade-card-head">
                <span class="upgrade-title">${c.title}</span>
                <span class="upgrade-badge ${c.category.toLowerCase()}">${c.badge}</span>
              </div>
              <p class="upgrade-desc">${c.desc}</p>
            </div>
          </button>
        `
          )
          .join('');

        upgradeCardsList.querySelectorAll('.upgrade-card-btn').forEach((btn) => {
          btn.addEventListener('click', () => {
            const upId = btn.getAttribute('data-id');
            if (upId && this.engine) {
              levelupModal.classList.remove('active');
              this.engine.applyUpgrade(upId);
            }
          });
        });

        levelupModal.classList.add('active');
      },
      onGameOver: (kills, timeSec, level) => {
        currentKills = kills;
        currentTimeSec = timeSec;
        currentLevel = level;

        modalKills.textContent = kills.toString();
        const mins = Math.floor(timeSec / 60);
        const secs = timeSec % 60;
        modalTime.textContent = `${mins}:${secs < 10 ? '0' : ''}${secs}`;
        modalLevel.textContent = `LV. ${level}`;

        gameoverModal.classList.add('active');
      },
    });

    const engine = this.engine;

    // Audio Toggle
    btnAudio.addEventListener('click', () => {
      engine.soundManager.toggleMute();
      btnAudio.innerHTML = engine.soundManager.isMuted() ? Icons.volumeMute : Icons.volume;
    });

    // Replay
    btnRestart.addEventListener('click', () => {
      gameoverModal.classList.remove('active');
      engine.start();
    });

    // Share to X
    btnShareX.addEventListener('click', () => {
      const text = `我在 SNEK Survivor 割草生還 ${currentTimeSec} 秒，斬獲 ${currentKills} 隻怪獸 (達到等級 LV.${currentLevel})！你能超越我嗎？\n\n#SNEK #Survivor #Cardano $SNEK`;
      const url = 'https://www.snek.com.tw/game/#/game/survivor';
      const tweetUrl = `https://twitter.com/intent/tweet?text=${encodeURIComponent(text)}&url=${encodeURIComponent(url)}`;
      window.open(tweetUrl, '_blank', 'noopener,noreferrer');
    });

    // Keyboard Controls
    const keysPressed: Record<string, boolean> = {};
    const updateMovementFromKeys = () => {
      let vx = 0;
      let vy = 0;
      if (keysPressed['KeyW'] || keysPressed['ArrowUp']) vy -= 1;
      if (keysPressed['KeyS'] || keysPressed['ArrowDown']) vy += 1;
      if (keysPressed['KeyA'] || keysPressed['ArrowLeft']) vx -= 1;
      if (keysPressed['KeyD'] || keysPressed['ArrowRight']) vx += 1;

      const len = Math.hypot(vx, vy);
      if (len > 0) {
        engine.setMoveVector(vx / len, vy / len);
      } else {
        engine.setMoveVector(0, 0);
      }
    };

    const onKeyDown = (e: KeyboardEvent) => {
      keysPressed[e.code] = true;
      updateMovementFromKeys();
    };
    const onKeyUp = (e: KeyboardEvent) => {
      keysPressed[e.code] = false;
      updateMovementFromKeys();
    };

    window.addEventListener('keydown', onKeyDown);
    window.addEventListener('keyup', onKeyUp);
    this.cleanups.push(() => {
      window.removeEventListener('keydown', onKeyDown);
      window.removeEventListener('keyup', onKeyUp);
    });

    // Touch Virtual Joystick & Direct Canvas Drag Controls
    let touchId: number | null = null;
    let centerX = 0;
    let centerY = 0;

    const updateJoystickMovement = (clientX: number, clientY: number) => {
      const dx = clientX - centerX;
      const dy = clientY - centerY;
      const dist = Math.hypot(dx, dy);
      const maxRadius = 36;

      const angle = Math.atan2(dy, dx);
      const clampedDist = Math.min(maxRadius, dist);
      const stickX = Math.cos(angle) * clampedDist;
      const stickY = Math.sin(angle) * clampedDist;

      joystickStick.style.transform = `translate(${stickX}px, ${stickY}px)`;

      if (dist > 5) {
        engine.setMoveVector(dx / dist, dy / dist);
      } else {
        engine.setMoveVector(0, 0);
      }
    };

    touchZone.addEventListener(
      'touchstart',
      (e: TouchEvent) => {
        if (e.touches.length > 0) {
          e.preventDefault();
          const t = e.touches[0];
          touchId = t.identifier;
          const baseRect = joystickBase.getBoundingClientRect();
          centerX = baseRect.left + baseRect.width / 2;
          centerY = baseRect.top + baseRect.height / 2;

          joystickStick.style.transition = 'none';
          updateJoystickMovement(t.clientX, t.clientY);
        }
      },
      { passive: false }
    );

    touchZone.addEventListener(
      'touchmove',
      (e: TouchEvent) => {
        if (touchId === null) return;
        for (let i = 0; i < e.touches.length; i++) {
          const t = e.touches[i];
          if (t.identifier === touchId) {
            e.preventDefault();
            updateJoystickMovement(t.clientX, t.clientY);
            break;
          }
        }
      },
      { passive: false }
    );

    const onTouchEnd = () => {
      touchId = null;
      joystickStick.style.transition = 'transform 0.15s ease';
      joystickStick.style.transform = 'translate(0px, 0px)';
      engine.setMoveVector(0, 0);
    };

    touchZone.addEventListener('touchend', onTouchEnd, { passive: true });
    touchZone.addEventListener('touchcancel', onTouchEnd, { passive: true });

    // Direct Canvas Drag Steering
    let canvasTouchId: number | null = null;
    let canvasStartX = 0;
    let canvasStartY = 0;

    canvasWrapper.addEventListener(
      'touchstart',
      (e: TouchEvent) => {
        if (levelupModal.classList.contains('active') || gameoverModal.classList.contains('active')) {
          return;
        }
        if (e.touches.length > 0) {
          const t = e.touches[0];
          canvasTouchId = t.identifier;
          canvasStartX = t.clientX;
          canvasStartY = t.clientY;
        }
      },
      { passive: true }
    );

    canvasWrapper.addEventListener(
      'touchmove',
      (e: TouchEvent) => {
        if (canvasTouchId === null) return;
        for (let i = 0; i < e.touches.length; i++) {
          const t = e.touches[i];
          if (t.identifier === canvasTouchId) {
            e.preventDefault();
            const dx = t.clientX - canvasStartX;
            const dy = t.clientY - canvasStartY;
            const dist = Math.hypot(dx, dy);
            if (dist > 8) {
              engine.setMoveVector(dx / dist, dy / dist);
            } else {
              engine.setMoveVector(0, 0);
            }
            break;
          }
        }
      },
      { passive: false }
    );

    const onCanvasTouchEnd = () => {
      canvasTouchId = null;
      if (touchId === null) {
        engine.setMoveVector(0, 0);
      }
    };

    canvasWrapper.addEventListener('touchend', onCanvasTouchEnd, { passive: true });
    canvasWrapper.addEventListener('touchcancel', onCanvasTouchEnd, { passive: true });

    // Start Engine
    engine.start();

    // Testing / Preview helper
    if (window.location.hash.includes('preview=levelup')) {
      engine.addExp(20);
    } else if (window.location.hash.includes('preview=cpi')) {
      engine.triggerMacroEventForTesting('CPI_SURGE');
    } else if (window.location.hash.includes('preview=nfp')) {
      engine.triggerMacroEventForTesting('NFP_REPORT');
    } else if (window.location.hash.includes('preview=battle')) {
      setTimeout(() => {
        engine.enemies.push(
          { id: 'b1', x: 140, y: 150, hp: 50, maxHp: 50, speed: 0.8, size: 20, type: 'BEAR', color: '#ff1744' },
          { id: 'c1', x: 300, y: 140, hp: 30, maxHp: 30, speed: 0.9, size: 16, type: 'RED_CANDLE', color: '#d50000' },
          { id: 'r1', x: 120, y: 290, hp: 40, maxHp: 40, speed: 1.2, size: 18, type: 'LIQUIDATION_REAPER', color: '#ea80fc', rotation: 0.5 },
          { id: 'w1', x: 310, y: 300, hp: 350, maxHp: 400, speed: 0.5, size: 36, type: 'WHALE_BOSS', color: '#40c4ff', isBoss: true }
        );
        engine.expGems.push(
          { id: 'g1', x: 180, y: 200, value: 1, angle: 0.2 },
          { id: 'g2', x: 260, y: 210, value: 2, angle: 0.8 },
          { id: 'g3', x: 230, y: 270, value: 5, angle: 1.5 }
        );
      }, 50);
    }

    return () => {
      if (this.engine) {
        this.engine.destroy();
        this.engine = null;
      }
      this.cleanups.forEach((c) => c());
      this.cleanups = [];
      this.container.innerHTML = '';
    };
  }
}
