import { FoodItem, Point } from '../types.ts';

export class FoodManager {
  public foods: FoodItem[] = [];
  private gridWidth: number;
  private gridHeight: number;
  private coinImage: HTMLImageElement = new Image();
  private imageLoaded: boolean = false;
  private adaSpawnTimer: number = 0;

  constructor(gridWidth: number = 24, gridHeight: number = 24) {
    this.gridWidth = gridWidth;
    this.gridHeight = gridHeight;
    this.coinImage.src = './assets/token/Snek-Square-BG 200x200.webp';
    this.coinImage.onload = () => {
      this.imageLoaded = true;
    };
  }

  public reset(snakeSegments: Point[]): void {
    this.foods = [];
    this.adaSpawnTimer = 0;
    this.spawnRegularCoin(snakeSegments);
  }

  private getRandomEmptyCell(snakeSegments: Point[]): Point | null {
    const occupied = new Set<string>();
    snakeSegments.forEach((p) => occupied.add(`${p.x},${p.y}`));
    this.foods.forEach((f) => occupied.add(`${f.position.x},${f.position.y}`));

    const available: Point[] = [];
    for (let x = 0; x < this.gridWidth; x++) {
      for (let y = 0; y < this.gridHeight; y++) {
        if (!occupied.has(`${x},${y}`)) {
          available.push({ x, y });
        }
      }
    }

    if (available.length === 0) return null;
    const index = Math.floor(Math.random() * available.length);
    return available[index];
  }

  public spawnRegularCoin(snakeSegments: Point[]): void {
    const pos = this.getRandomEmptyCell(snakeSegments);
    if (!pos) return;

    this.foods.push({
      id: `coin_${Date.now()}_${Math.random()}`,
      type: 'snek_coin',
      position: pos,
      points: 10,
      growth: 1,
      spawnTimeMs: performance.now(),
      color: '#00e676',
    });
  }

  public spawnAdaGem(snakeSegments: Point[]): void {
    const pos = this.getRandomEmptyCell(snakeSegments);
    if (!pos) return;

    this.foods.push({
      id: `ada_${Date.now()}`,
      type: 'ada_gem',
      position: pos,
      points: 50,
      growth: 2,
      durationMs: 9000, // 9 seconds to claim
      spawnTimeMs: performance.now(),
      color: '#00b0ff',
    });
  }

  public update(dt: number, snakeSegments: Point[], currentScore: number): void {
    const now = performance.now();

    // Check expiration of temporary foods (like ADA gem)
    for (let i = this.foods.length - 1; i >= 0; i--) {
      const food = this.foods[i];
      if (food.durationMs) {
        if (now - food.spawnTimeMs >= food.durationMs) {
          this.foods.splice(i, 1);
        }
      }
    }

    // Ensure at least one regular coin is on the board
    const hasRegular = this.foods.some((f) => f.type === 'snek_coin');
    if (!hasRegular) {
      this.spawnRegularCoin(snakeSegments);
    }

    // Chance to spawn ADA Gem every 15-25 seconds after score > 30
    if (currentScore >= 30) {
      this.adaSpawnTimer += dt;
      const hasAda = this.foods.some((f) => f.type === 'ada_gem');
      if (!hasAda && this.adaSpawnTimer > 15000) {
        if (Math.random() < 0.35) {
          this.spawnAdaGem(snakeSegments);
          this.adaSpawnTimer = 0;
        } else {
          this.adaSpawnTimer = 10000; // try again sooner
        }
      }
    }
  }

  public checkCollision(head: Point): FoodItem | null {
    const index = this.foods.findIndex(
      (f) => f.position.x === head.x && f.position.y === head.y
    );
    if (index !== -1) {
      const eaten = this.foods[index];
      this.foods.splice(index, 1);
      return eaten;
    }
    return null;
  }

  public render(ctx: CanvasRenderingContext2D, cellSize: number): void {
    const now = performance.now();

    for (const food of this.foods) {
      const cx = food.position.x * cellSize + cellSize / 2;
      const cy = food.position.y * cellSize + cellSize / 2;

      ctx.save();
      ctx.translate(cx, cy);

      // Breathing / floating pulse
      const pulse = 1 + Math.sin(now / 180) * 0.08;
      ctx.scale(pulse, pulse);

      if (food.type === 'snek_coin') {
        // SNEK Token
        const size = cellSize * 1.1;
        ctx.shadowColor = '#00e676';
        ctx.shadowBlur = 12;

        if (this.imageLoaded && this.coinImage.complete) {
          ctx.drawImage(this.coinImage, -size / 2, -size / 2, size, size);
        } else {
          ctx.beginPath();
          ctx.arc(0, 0, cellSize / 2.2, 0, Math.PI * 2);
          ctx.fillStyle = '#00e676';
          ctx.fill();
        }
      } else if (food.type === 'ada_gem') {
        // ADA Gem with remaining duration countdown ring
        const size = cellSize * 1.15;
        ctx.shadowColor = '#00b0ff';
        ctx.shadowBlur = 16;

        // Outer rotating diamond
        ctx.rotate(now / 500);
        ctx.fillStyle = '#00b0ff';
        ctx.beginPath();
        ctx.moveTo(0, -size / 2);
        ctx.lineTo(size / 2, 0);
        ctx.lineTo(0, size / 2);
        ctx.lineTo(-size / 2, 0);
        ctx.closePath();
        ctx.fill();

        // Inner glowing core
        ctx.fillStyle = '#ffffff';
        ctx.beginPath();
        ctx.arc(0, 0, size * 0.22, 0, Math.PI * 2);
        ctx.fill();

        // Duration ring
        if (food.durationMs) {
          const elapsed = now - food.spawnTimeMs;
          const ratio = Math.max(0, 1 - elapsed / food.durationMs);
          ctx.beginPath();
          ctx.arc(0, 0, size * 0.65, -Math.PI / 2, -Math.PI / 2 + Math.PI * 2 * ratio);
          ctx.strokeStyle = '#ffd700';
          ctx.lineWidth = 2.5;
          ctx.stroke();
        }
      }

      ctx.restore();
    }
  }
}
