import { SoundManager } from '../../audio/SoundManager.ts';
import { ParticleSystem } from '../../engine/ParticleSystem.ts';
import { MACRO_EVENTS, MacroEvent } from './data/events.ts';
import { TALENTS_POOL, TalentDef } from './data/talents.ts';
import { getSurvivorPath2D } from './data/icons.ts';

export type EnemyType = 'BEAR' | 'RED_CANDLE' | 'LIQUIDATION_REAPER' | 'WHALE_BOSS';

export interface Enemy {
  id: string;
  x: number;
  y: number;
  hp: number;
  maxHp: number;
  speed: number;
  size: number;
  type: EnemyType;
  color: string;
  rotation?: number;
  isBoss?: boolean;
}

export interface Projectile {
  x: number;
  y: number;
  vx: number;
  vy: number;
  damage: number;
  life: number;
}

export interface ExpGem {
  id: string;
  x: number;
  y: number;
  value: number;
  angle?: number;
}

export interface SurvivorCallbacks {
  onHpChange: (hp: number, maxHp: number) => void;
  onExpChange: (exp: number, nextExp: number, level: number) => void;
  onKillsChange: (kills: number) => void;
  onTimerChange: (seconds: number) => void;
  onLevelUp: (choices: TalentDef[]) => void;
  onGameOver: (kills: number, timeSec: number, level: number) => void;
  onMacroEvent?: (event: MacroEvent | null, remainingSec: number) => void;
}

export class SurvivorEngine {
  public canvas: HTMLCanvasElement;
  public ctx: CanvasRenderingContext2D;
  private callbacks: SurvivorCallbacks;
  public soundManager: SoundManager;
  public particleSystem: ParticleSystem;

  // Arena Dimensions
  public width: number = 440;
  public height: number = 440;

  // Player (SNEK - Head unchanged)
  public px: number = 220;
  public py: number = 220;
  public pvx: number = 0;
  public pvy: number = 0;
  public hp: number = 100;
  public maxHp: number = 100;
  public speed: number = 2.4;
  public playerSize: number = 18;
  public damageReduction: number = 0;
  public damageMultiplier: number = 1.0;
  public magnetRadius: number = 65;
  public hasCompoundInterest: boolean = false;

  // Stats & Progression
  public level: number = 1;
  public exp: number = 0;
  public nextExp: number = 5;
  public kills: number = 0;
  public elapsedTime: number = 0;

  // Weapon Stats
  public venomCount: number = 1;
  public venomCooldown: number = 420;
  private venomTimer: number = 0;
  public orbitCount: number = 1;
  public orbitSpeed: number = 0.05;
  private orbitAngle: number = 0;

  // Macroeconomic Event System
  public activeEvent: MacroEvent | null = null;
  public eventTimer: number = 0;
  public nextEventTimer: number = 18;

  // Game Entities
  public enemies: Enemy[] = [];
  public projectiles: Projectile[] = [];
  public expGems: ExpGem[] = [];

  // Ambient Candlesticks for Trading Floor
  private bgCandles: { x: number; y: number; h: number; isUp: boolean }[] = [];

  // State
  public isRunning: boolean = false;
  public isPaused: boolean = false;
  private lastTime: number = 0;
  private spawnTimer: number = 0;
  private animFrameId: number | null = null;
  private invulnerableTimer: number = 0;

  // Head sprite (Unchanged SNEK mascot)
  private headImage: HTMLImageElement = new Image();
  private imageLoaded: boolean = false;

  constructor(canvas: HTMLCanvasElement, callbacks: SurvivorCallbacks) {
    this.canvas = canvas;
    const ctx = canvas.getContext('2d');
    if (!ctx) throw new Error('No 2D context');
    this.ctx = ctx;
    this.callbacks = callbacks;
    this.soundManager = new SoundManager();
    this.particleSystem = new ParticleSystem();

    // Preserve original SNEK head face sprite
    this.headImage.src = './assets/face/SNEK_0004.webp';
    this.headImage.onload = () => {
      this.imageLoaded = true;
    };

    this.initCanvasSize();
    this.initBgCandles();
  }

  private initCanvasSize(): void {
    const dpr = window.devicePixelRatio || 1;
    this.canvas.width = this.width * dpr;
    this.canvas.height = this.height * dpr;
    this.ctx.scale(dpr, dpr);
  }

  private initBgCandles(): void {
    this.bgCandles = [];
    for (let x = 0; x < this.width + 40; x += 28) {
      this.bgCandles.push({
        x,
        y: 120 + Math.random() * 200,
        h: 20 + Math.random() * 45,
        isUp: Math.random() > 0.48,
      });
    }
  }

  public start(): void {
    this.soundManager.unlock();
    this.px = this.width / 2;
    this.py = this.height / 2;
    this.pvx = 0;
    this.pvy = 0;
    this.hp = 100;
    this.maxHp = 100;
    this.speed = 2.4;
    this.level = 1;
    this.exp = 0;
    this.nextExp = 5;
    this.kills = 0;
    this.elapsedTime = 0;
    this.damageReduction = 0;
    this.damageMultiplier = 1.0;
    this.magnetRadius = 65;
    this.hasCompoundInterest = false;

    this.venomCount = 1;
    this.venomCooldown = 420;
    this.orbitCount = 1;
    this.orbitSpeed = 0.05;
    this.enemies = [];
    this.projectiles = [];
    this.expGems = [];
    this.activeEvent = null;
    this.eventTimer = 0;
    this.nextEventTimer = 18;
    this.particleSystem.clear();

    this.isRunning = true;
    this.isPaused = false;
    this.lastTime = performance.now();

    this.callbacks.onHpChange(this.hp, this.maxHp);
    this.callbacks.onExpChange(this.exp, this.nextExp, this.level);
    this.callbacks.onKillsChange(this.kills);
    this.callbacks.onTimerChange(0);
    this.callbacks.onMacroEvent?.(null, 0);

    this.loop(this.lastTime);
  }

  public pause(): void {
    this.isPaused = true;
  }

  public resume(): void {
    this.isPaused = false;
    this.lastTime = performance.now();
  }

  public setMoveVector(vx: number, vy: number): void {
    this.pvx = vx;
    this.pvy = vy;
  }

  public applyUpgrade(upgradeId: string): void {
    switch (upgradeId) {
      case 'LIQUIDITY_INJECTION':
      case 'MULTI_VENOM':
        this.venomCount = Math.min(5, this.venomCount + 1);
        this.venomCooldown = Math.max(220, this.venomCooldown - 35);
        break;
      case 'HEDGE_OPTIONS_SHIELD':
      case 'BURN_AURA':
        this.orbitCount = Math.min(5, this.orbitCount + 1);
        this.orbitSpeed += 0.016;
        break;
      case 'ARBITRAGE_SPRINT':
      case 'SLITHER_SPEED':
        this.speed *= 1.20;
        break;
      case 'DIAMOND_HANDS':
        this.maxHp += 30;
        this.hp = this.maxHp;
        this.damageReduction = Math.min(0.3, this.damageReduction + 0.1);
        this.callbacks.onHpChange(this.hp, this.maxHp);
        break;
      case 'FED_QE_PIVOT':
      case 'MEGA_BURN':
        // Kill all normal enemies currently alive
        for (const e of this.enemies) {
          if (!e.isBoss) {
            this.particleSystem.emitDeath(e.x, e.y);
            this.expGems.push({ id: `gem_${Math.random()}`, x: e.x, y: e.y, value: 1 });
          }
        }
        this.kills += this.enemies.filter(e => !e.isBoss).length;
        this.enemies = this.enemies.filter(e => e.isBoss);
        this.callbacks.onKillsChange(this.kills);
        this.soundManager.playHighScore();
        break;
      case 'WHALE_MAGNET':
        this.magnetRadius *= 2.0;
        break;
      case 'COMPOUND_INTEREST':
        this.hasCompoundInterest = true;
        this.damageMultiplier *= 1.15;
        break;
    }
    this.resume();
  }

  public triggerMacroEventForTesting(eventId: string): void {
    const ev = MACRO_EVENTS.find((m) => m.id === eventId) || MACRO_EVENTS[0];
    this.activeEvent = ev;
    this.eventTimer = ev.durationSec;
    if (ev.effect.spawnWhaleBoss) {
      this.spawnWhaleBoss();
    }
    if (ev.effect.spawnReaper) {
      for (let k = 0; k < 4; k++) {
        this.spawnEnemy('LIQUIDATION_REAPER');
      }
    }
    this.callbacks.onMacroEvent?.(this.activeEvent, Math.ceil(this.eventTimer));
  }

  public addExp(amount: number): void {
    this.exp += amount;
    if (this.exp >= this.nextExp) {
      this.handleLevelUp();
    } else {
      this.callbacks.onExpChange(this.exp, this.nextExp, this.level);
    }
  }

  private loop = (timestamp: number): void => {
    if (!this.isRunning) return;

    const dt = timestamp - this.lastTime;
    this.lastTime = timestamp;

    if (!this.isPaused) {
      this.update(dt);
    }
    this.render(dt);

    this.animFrameId = requestAnimationFrame(this.loop);
  };

  public destroy(): void {
    this.isRunning = false;
    if (this.animFrameId !== null) {
      cancelAnimationFrame(this.animFrameId);
    }
  }

  private update(dt: number): void {
    this.elapsedTime += dt / 1000;
    this.callbacks.onTimerChange(Math.floor(this.elapsedTime));
    this.particleSystem.update(dt);

    if (this.invulnerableTimer > 0) {
      this.invulnerableTimer -= dt;
    }

    // 1. Move Player
    let currentSpeed = this.speed;
    if (this.activeEvent?.effect.playerSpeedMult) {
      currentSpeed *= this.activeEvent.effect.playerSpeedMult;
    }

    this.px = Math.max(this.playerSize, Math.min(this.width - this.playerSize, this.px + this.pvx * currentSpeed));
    this.py = Math.max(this.playerSize, Math.min(this.height - this.playerSize, this.py + this.pvy * currentSpeed));

    // Arbitrage Sprint Electric Particle Trail
    if (Math.hypot(this.pvx, this.pvy) > 0.1 && Math.random() < 0.25) {
      this.particleSystem.emitBurnDash(this.px, this.py, Math.random() * Math.PI * 2);
    }

    // 2. Macroeconomic Financial Event Scheduler
    if (!this.activeEvent) {
      this.nextEventTimer -= dt / 1000;
      if (this.nextEventTimer <= 0) {
        // Trigger next macro event
        const event = MACRO_EVENTS[Math.floor(Math.random() * MACRO_EVENTS.length)];
        this.activeEvent = event;
        this.eventTimer = event.durationSec;
        this.nextEventTimer = 28 + Math.random() * 12;

        if (event.effect.spawnWhaleBoss) {
          this.spawnWhaleBoss();
        }
        if (event.effect.spawnReaper) {
          for (let k = 0; k < 5; k++) {
            this.spawnEnemy('LIQUIDATION_REAPER');
          }
        }

        this.soundManager.playBoost();
        this.callbacks.onMacroEvent?.(this.activeEvent, Math.ceil(this.eventTimer));
      }
    } else {
      this.eventTimer -= dt / 1000;
      if (this.eventTimer <= 0) {
        this.activeEvent = null;
        this.callbacks.onMacroEvent?.(null, 0);
      } else {
        this.callbacks.onMacroEvent?.(this.activeEvent, Math.ceil(this.eventTimer));
        if (this.activeEvent.effect.burnAllTickDamage) {
          // Apply short squeeze tick burn every frame partially
          for (let j = this.enemies.length - 1; j >= 0; j--) {
            const e = this.enemies[j];
            e.hp -= (dt / 1000) * 12;
            if (Math.random() < 0.08) {
              this.particleSystem.emitBurnDash(e.x, e.y, -Math.PI / 2);
            }
            if (e.hp <= 0) {
              this.killEnemy(j);
            }
          }
        }
      }
    }

    // 3. Spawn Normal Enemies
    this.spawnTimer += dt;
    let spawnInterval = Math.max(450, 1500 - this.elapsedTime * 15);
    if (this.activeEvent?.effect.spawnRateMult) {
      spawnInterval /= this.activeEvent.effect.spawnRateMult;
    }

    if (this.spawnTimer >= spawnInterval) {
      this.spawnTimer = 0;
      this.spawnEnemy();
    }

    // 4. Move Enemies towards Player
    for (let i = this.enemies.length - 1; i >= 0; i--) {
      const e = this.enemies[i];
      const dx = this.px - e.x;
      const dy = this.py - e.y;
      const dist = Math.hypot(dx, dy);

      if (dist > 0) {
        let speed = e.speed;
        if (this.activeEvent?.effect.enemySpeedMult && !e.isBoss) {
          speed *= this.activeEvent.effect.enemySpeedMult;
        }
        e.x += (dx / dist) * speed;
        e.y += (dy / dist) * speed;
      }

      if (e.type === 'LIQUIDATION_REAPER') {
        e.rotation = (e.rotation || 0) + 0.12;
      }

      // Check collision with Player
      if (dist < this.playerSize + e.size && this.invulnerableTimer <= 0) {
        const rawDmg = e.isBoss ? 24 : (e.type === 'LIQUIDATION_REAPER' ? 14 : 10);
        const finalDmg = Math.max(2, Math.floor(rawDmg * (1 - this.damageReduction)));
        this.hp -= finalDmg;
        this.invulnerableTimer = 650;
        this.soundManager.playDie();
        this.callbacks.onHpChange(Math.max(0, this.hp), this.maxHp);

        if (this.hp <= 0) {
          this.handleGameOver();
          return;
        }
      }
    }

    // 5. Auto Fire Venom Shot (Liquidity Injection)
    this.venomTimer += dt;
    let effectiveCooldown = this.venomCooldown;
    if (this.activeEvent?.effect.playerAttackSpeedMult) {
      effectiveCooldown /= this.activeEvent.effect.playerAttackSpeedMult;
    }

    if (this.venomTimer >= effectiveCooldown && this.enemies.length > 0) {
      this.venomTimer = 0;
      this.fireVenom();
    }

    // 6. Update Projectiles
    for (let i = this.projectiles.length - 1; i >= 0; i--) {
      const p = this.projectiles[i];
      p.x += p.vx;
      p.y += p.vy;
      p.life -= dt;

      let hit = false;
      for (let j = this.enemies.length - 1; j >= 0; j--) {
        const e = this.enemies[j];
        if (Math.hypot(p.x - e.x, p.y - e.y) < e.size + 6) {
          e.hp -= p.damage * this.damageMultiplier;
          this.particleSystem.emitEat(p.x, p.y);
          hit = true;

          if (e.hp <= 0) {
            this.killEnemy(j);
          }
          break;
        }
      }

      if (hit || p.life <= 0) {
        this.projectiles.splice(i, 1);
      }
    }

    // 7. Update Orbit Burn Shield (Options Hedging Shield)
    this.orbitAngle += this.orbitSpeed;
    const orbitRadius = 45;
    for (let o = 0; o < this.orbitCount; o++) {
      const angle = this.orbitAngle + (o * Math.PI * 2) / this.orbitCount;
      const ox = this.px + Math.cos(angle) * orbitRadius;
      const oy = this.py + Math.sin(angle) * orbitRadius;

      // Orbit damage to colliding enemies
      for (let j = this.enemies.length - 1; j >= 0; j--) {
        const e = this.enemies[j];
        if (Math.hypot(ox - e.x, oy - e.y) < e.size + 10) {
          e.hp -= 1.8 * this.damageMultiplier;
          this.particleSystem.emitBurnDash(ox, oy, angle);
          if (e.hp <= 0) {
            this.killEnemy(j);
          }
        }
      }
    }

    // 8. Collect EXP Gems
    const effectiveMagnet = this.activeEvent?.effect.magnetAll ? 9999 : this.magnetRadius;
    for (let i = this.expGems.length - 1; i >= 0; i--) {
      const g = this.expGems[i];
      const dist = Math.hypot(this.px - g.x, this.py - g.y);
      g.angle = (g.angle || 0) + 0.05;

      if (dist < effectiveMagnet) {
        // Accelerate towards player
        g.x += ((this.px - g.x) / dist) * 7.5;
        g.y += ((this.py - g.y) / dist) * 7.5;

        if (dist < this.playerSize + 8) {
          this.exp += g.value;
          this.expGems.splice(i, 1);
          this.soundManager.playEat();

          if (this.exp >= this.nextExp) {
            this.handleLevelUp();
          } else {
            this.callbacks.onExpChange(this.exp, this.nextExp, this.level);
          }
        }
      }
    }
  }

  private spawnEnemy(forceType?: EnemyType): void {
    const side = Math.floor(Math.random() * 4);
    let x = 0;
    let y = 0;

    switch (side) {
      case 0: x = Math.random() * this.width; y = -24; break;
      case 1: x = this.width + 24; y = Math.random() * this.height; break;
      case 2: x = Math.random() * this.width; y = this.height + 24; break;
      case 3: x = -24; y = Math.random() * this.height; break;
    }

    const rand = Math.random();
    let type: EnemyType = forceType || (rand < 0.45 ? 'RED_CANDLE' : (rand < 0.70 ? 'BEAR' : 'LIQUIDATION_REAPER'));
    let hp = 30;
    let speed = 0.95;
    let size = 15;
    let color = '#d50000';

    if (type === 'RED_CANDLE') {
      hp = 18;
      speed = 1.45;
      size = 12;
      color = '#ff1744';
    } else if (type === 'LIQUIDATION_REAPER') {
      hp = 14;
      speed = 2.15;
      size = 13;
      color = '#e040fb';
    } else {
      type = 'BEAR';
      hp = 36;
      speed = 0.90;
      size = 16;
      color = '#d50000';
    }

    if (this.activeEvent?.effect.enemySpeedMult) {
      speed *= this.activeEvent.effect.enemySpeedMult;
    }

    this.enemies.push({
      id: `enemy_${Date.now()}_${Math.random()}`,
      x,
      y,
      hp,
      maxHp: hp,
      speed,
      size,
      type,
      color,
      rotation: 0,
    });
  }

  private spawnWhaleBoss(): void {
    if (this.enemies.some(e => e.type === 'WHALE_BOSS')) return;

    this.enemies.push({
      id: `boss_whale_${Date.now()}`,
      x: this.width / 2,
      y: -50,
      hp: 360,
      maxHp: 360,
      speed: 0.65,
      size: 32,
      type: 'WHALE_BOSS',
      color: '#00b0ff',
      isBoss: true,
      rotation: 0,
    });
  }

  private fireVenom(): void {
    let closest: Enemy | null = null;
    let minDist = Infinity;
    for (const e of this.enemies) {
      const d = Math.hypot(this.px - e.x, this.py - e.y);
      if (d < minDist) {
        minDist = d;
        closest = e;
      }
    }

    if (!closest) return;
    const baseAngle = Math.atan2(closest.y - this.py, closest.x - this.px);
    const speed = 7.5;

    for (let i = 0; i < this.venomCount; i++) {
      const spread = (i - (this.venomCount - 1) / 2) * 0.22;
      const angle = baseAngle + spread;
      this.projectiles.push({
        x: this.px,
        y: this.py,
        vx: Math.cos(angle) * speed,
        vy: Math.sin(angle) * speed,
        damage: 22,
        life: 1500,
      });
    }

    this.soundManager.playBoost();
  }

  private killEnemy(idx: number): void {
    const e = this.enemies[idx];
    this.enemies.splice(idx, 1);
    this.kills++;
    this.callbacks.onKillsChange(this.kills);
    this.particleSystem.emitDeath(e.x, e.y);

    if (this.hasCompoundInterest && this.kills % 15 === 0) {
      this.damageMultiplier = Math.min(3.0, this.damageMultiplier + 0.05);
    }

    const dropMultiplier = this.activeEvent?.effect.expDropMult || 1;
    const count = e.isBoss ? 15 : (Math.random() < 0.2 ? 2 : 1);
    for (let i = 0; i < count * dropMultiplier; i++) {
      const offsetX = (Math.random() - 0.5) * (e.isBoss ? 48 : 12);
      const offsetY = (Math.random() - 0.5) * (e.isBoss ? 48 : 12);
      this.expGems.push({
        id: `gem_${Math.random()}`,
        x: e.x + offsetX,
        y: e.y + offsetY,
        value: 1,
      });
    }
  }

  private handleLevelUp(): void {
    this.level++;
    this.exp = 0;
    this.nextExp = Math.floor(this.nextExp * 1.5);
    this.soundManager.playHighScore();
    this.callbacks.onExpChange(this.exp, this.nextExp, this.level);

    // Pick 3 random financial talents
    const shuffled = [...TALENTS_POOL].sort(() => 0.5 - Math.random()).slice(0, 3);
    this.pause();
    this.callbacks.onLevelUp(shuffled);
  }

  private handleGameOver(): void {
    this.isRunning = false;
    this.soundManager.playDie();
    this.particleSystem.emitDeath(this.px, this.py);
    this.callbacks.onGameOver(this.kills, Math.floor(this.elapsedTime), this.level);
  }

  private render(dt: number): void {
    const ctx = this.ctx;
    ctx.save();

    // 1. Cyber Trading Floor Dark Gradient Background
    const bgGrad = ctx.createRadialGradient(
      this.width / 2, this.height / 2, 30,
      this.width / 2, this.height / 2, this.width * 0.75
    );
    bgGrad.addColorStop(0, '#0c121d');
    bgGrad.addColorStop(1, '#070a0f');
    ctx.fillStyle = bgGrad;
    ctx.fillRect(0, 0, this.width, this.height);

    // 2. Ambient K-Line Candlestick Waves
    for (let i = 0; i < this.bgCandles.length; i++) {
      const c = this.bgCandles[i];
      c.x -= (dt / 1000) * 12;
      if (c.x < -30) {
        c.x = this.width + 10;
        c.h = 20 + Math.random() * 45;
        c.isUp = Math.random() > 0.48;
      }

      ctx.fillStyle = c.isUp ? 'rgba(0, 230, 118, 0.07)' : 'rgba(255, 23, 68, 0.07)';
      ctx.fillRect(c.x, c.y, 14, c.h);
      ctx.strokeStyle = c.isUp ? 'rgba(0, 230, 118, 0.12)' : 'rgba(255, 23, 68, 0.12)';
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.moveTo(c.x + 7, c.y - 8);
      ctx.lineTo(c.x + 7, c.y + c.h + 8);
      ctx.stroke();
    }

    // 3. Trading Grid & Coordinates
    ctx.strokeStyle = 'rgba(0, 230, 118, 0.04)';
    ctx.lineWidth = 1;
    for (let x = 0; x < this.width; x += 32) {
      ctx.beginPath();
      ctx.moveTo(x, 0);
      ctx.lineTo(x, this.height);
      ctx.stroke();
    }
    for (let y = 0; y < this.height; y += 32) {
      ctx.beginPath();
      ctx.moveTo(0, y);
      ctx.lineTo(this.width, y);
      ctx.stroke();
    }

    // 4. Event Ambient Pulse Border
    if (this.activeEvent) {
      ctx.strokeStyle = this.activeEvent.borderColor;
      ctx.lineWidth = 2.5;
      ctx.shadowColor = this.activeEvent.glowColor;
      ctx.shadowBlur = 14;
      ctx.strokeRect(2, 2, this.width - 4, this.height - 4);
    } else {
      ctx.strokeStyle = '#00e676';
      ctx.lineWidth = 1.5;
      ctx.shadowColor = '#00e676';
      ctx.shadowBlur = 8;
      ctx.strokeRect(1, 1, this.width - 2, this.height - 2);
    }
    ctx.shadowBlur = 0;

    // 5. Render Particles
    this.particleSystem.render(ctx);

    // 6. Render EXP Gems (Golden / ADA Crypto Coins)
    for (const g of this.expGems) {
      ctx.save();
      ctx.translate(g.x, g.y);
      ctx.rotate(g.angle || 0);

      // Gold Glow
      ctx.shadowColor = '#ffd700';
      ctx.shadowBlur = 8;
      ctx.fillStyle = '#ffd700';
      ctx.beginPath();
      ctx.arc(0, 0, 4.5, 0, Math.PI * 2);
      ctx.fill();

      // Inner Diamond Core
      ctx.fillStyle = '#00e676';
      ctx.fillRect(-1.5, -1.5, 3, 3);
      ctx.restore();
    }

    // 7. Render Projectiles (Liquidity Multi-Order Bullets)
    for (const p of this.projectiles) {
      ctx.save();
      ctx.translate(p.x, p.y);
      ctx.fillStyle = '#69f0ae';
      ctx.shadowColor = '#00e676';
      ctx.shadowBlur = 10;
      ctx.beginPath();
      ctx.arc(0, 0, 5, 0, Math.PI * 2);
      ctx.fill();

      // Core white bullet center
      ctx.fillStyle = '#ffffff';
      ctx.beginPath();
      ctx.arc(0, 0, 2.5, 0, Math.PI * 2);
      ctx.fill();
      ctx.restore();
    }

    // 8. Render Orbit Burn Shield (Options Hedging Shield)
    const orbitRadius = 45;
    for (let o = 0; o < this.orbitCount; o++) {
      const angle = this.orbitAngle + (o * Math.PI * 2) / this.orbitCount;
      const ox = this.px + Math.cos(angle) * orbitRadius;
      const oy = this.py + Math.sin(angle) * orbitRadius;

      ctx.save();
      ctx.translate(ox, oy);
      ctx.rotate(angle);

      ctx.fillStyle = '#ff9100';
      ctx.shadowColor = '#ff3d00';
      ctx.shadowBlur = 14;

      // Draw SVG shield path
      const shieldPath = getSurvivorPath2D('shield');
      if (shieldPath) {
        ctx.scale(18 / 512, 18 / 512);
        ctx.translate(-256, -256);
        ctx.fillStyle = '#ff9100';
        ctx.fill(shieldPath);
      } else {
        ctx.beginPath();
        ctx.arc(0, 0, 7, 0, Math.PI * 2);
        ctx.fill();
      }
      ctx.restore();
    }

    // 9. Render Financial Themed Enemies
    for (const e of this.enemies) {
      ctx.save();
      ctx.translate(e.x, e.y);

      if (e.type === 'RED_CANDLE') {
        // Red Candlestick
        ctx.shadowColor = '#ff1744';
        ctx.shadowBlur = 10;
        ctx.fillStyle = '#d50000';
        ctx.fillRect(-e.size / 2, -e.size / 2, e.size, e.size * 1.6);
        ctx.strokeStyle = '#ff8a80';
        ctx.lineWidth = 1.8;
        ctx.beginPath();
        ctx.moveTo(0, -e.size / 2 - 6);
        ctx.lineTo(0, e.size / 2 + 6);
        ctx.stroke();

        const candlePath = getSurvivorPath2D('candle');
        if (candlePath) {
          ctx.scale((e.size * 0.9) / 512, (e.size * 0.9) / 512);
          ctx.translate(-256, -256);
          ctx.fillStyle = '#ffebee';
          ctx.fill(candlePath);
        }
      } else if (e.type === 'LIQUIDATION_REAPER') {
        // Spinning Reaper Scythe
        ctx.rotate(e.rotation || 0);
        ctx.shadowColor = '#e040fb';
        ctx.shadowBlur = 12;

        const reaperPath = getSurvivorPath2D('reaper');
        if (reaperPath) {
          ctx.scale((e.size * 2.2) / 512, (e.size * 2.2) / 512);
          ctx.translate(-256, -256);
          ctx.fillStyle = '#ea80fc';
          ctx.fill(reaperPath);
        } else {
          ctx.fillStyle = '#e040fb';
          ctx.beginPath();
          ctx.arc(0, 0, e.size, 0, Math.PI * 2);
          ctx.fill();
        }
      } else if (e.type === 'WHALE_BOSS') {
        // Cyber Whale Boss
        ctx.shadowColor = '#00b0ff';
        ctx.shadowBlur = 22;

        const whalePath = getSurvivorPath2D('whale');
        if (whalePath) {
          ctx.scale((e.size * 2.4) / 512, (e.size * 2.4) / 512);
          ctx.translate(-256, -256);
          ctx.fillStyle = '#40c4ff';
          ctx.fill(whalePath);
        }

        // Floating Boss Health Bar
        const barW = e.size * 2.2;
        const barH = 5;
        ctx.fillStyle = '#1e293b';
        ctx.fillRect(-barW / 2, -e.size - 12, barW, barH);
        const hpRatio = Math.max(0, e.hp / e.maxHp);
        ctx.fillStyle = '#00b0ff';
        ctx.fillRect(-barW / 2, -e.size - 12, barW * hpRatio, barH);
      } else {
        // Bear Market Beast
        ctx.shadowColor = '#ff1744';
        ctx.shadowBlur = 12;
        ctx.fillStyle = 'rgba(213, 0, 0, 0.25)';
        ctx.beginPath();
        ctx.arc(0, 0, e.size, 0, Math.PI * 2);
        ctx.fill();

        const bearPath = getSurvivorPath2D('bear');
        if (bearPath) {
          ctx.scale((e.size * 2.0) / 512, (e.size * 2.0) / 512);
          ctx.translate(-256, -256);
          ctx.fillStyle = '#ff1744';
          ctx.fill(bearPath);
        } else {
          ctx.fillStyle = '#d50000';
          ctx.beginPath();
          ctx.arc(0, 0, e.size, 0, Math.PI * 2);
          ctx.fill();
        }
      }

      ctx.restore();
    }

    // 10. Render Player (SNEK Mascot Face - Unchanged)
    ctx.save();
    ctx.translate(this.px, this.py);

    if (this.invulnerableTimer > 0 && Math.floor(performance.now() / 80) % 2 === 0) {
      ctx.globalAlpha = 0.45;
    }

    // Multi-Ring Bullish Aura
    ctx.strokeStyle = 'rgba(0, 230, 118, 0.4)';
    ctx.lineWidth = 1.5;
    ctx.beginPath();
    ctx.arc(0, 0, this.playerSize * 1.35, 0, Math.PI * 2);
    ctx.stroke();

    // SNEK Head Image (Unchanged)
    if (this.imageLoaded && this.headImage.complete) {
      const s = this.playerSize * 2.2;
      ctx.shadowColor = '#00e676';
      ctx.shadowBlur = 12;
      ctx.drawImage(this.headImage, -s / 2, -s / 2, s, s);
    } else {
      ctx.fillStyle = '#00e676';
      ctx.beginPath();
      ctx.arc(0, 0, this.playerSize, 0, Math.PI * 2);
      ctx.fill();
    }

    ctx.restore();
    ctx.restore();
  }
}
