export class ShareCardGenerator {
  public static async generateCard(score: number, length: number, durationSeconds: number): Promise<HTMLCanvasElement> {
    const card = document.createElement('canvas');
    const width = 1200;
    const height = 675; // Standard 16:9 Twitter Card
    card.width = width;
    card.height = height;

    const ctx = card.getContext('2d');
    if (!ctx) return card;

    // 1. Background (Snek Dark Gradient)
    const bgGrad = ctx.createLinearGradient(0, 0, width, height);
    bgGrad.addColorStop(0, '#141715');
    bgGrad.addColorStop(0.5, '#1b211d');
    bgGrad.addColorStop(1, '#0e110f');
    ctx.fillStyle = bgGrad;
    ctx.fillRect(0, 0, width, height);

    // Subtle Grid pattern
    ctx.strokeStyle = 'rgba(43, 216, 142, 0.08)';
    ctx.lineWidth = 1;
    for (let x = 0; x < width; x += 40) {
      ctx.beginPath();
      ctx.moveTo(x, 0);
      ctx.lineTo(x, height);
      ctx.stroke();
    }
    for (let y = 0; y < height; y += 40) {
      ctx.beginPath();
      ctx.moveTo(0, y);
      ctx.lineTo(width, y);
      ctx.stroke();
    }

    // Glowing Neon Border
    ctx.strokeStyle = '#2bd88e';
    ctx.lineWidth = 4;
    ctx.shadowColor = '#2bd88e';
    ctx.shadowBlur = 24;
    ctx.strokeRect(20, 20, width - 40, height - 40);
    ctx.shadowBlur = 0;

    // 2. SNEK Header & Logo
    ctx.fillStyle = '#ffffff';
    ctx.font = 'bold 36px "Courier New", monospace, sans-serif';
    ctx.fillText('SNEK ARCADE | TAIWAN', 60, 90);

    ctx.fillStyle = '#2bd88e';
    ctx.font = '20px monospace';
    ctx.fillText('CARDANO MEME COMMUNITY POWERHOUSE', 60, 125);

    // 3. Huge Score Display Box
    const boxX = 60;
    const boxY = 170;
    const boxW = width - 120;
    const boxH = 340;

    ctx.fillStyle = 'rgba(43, 216, 142, 0.06)';
    ctx.strokeStyle = 'rgba(43, 216, 142, 0.35)';
    ctx.lineWidth = 2;
    ctx.fillRect(boxX, boxY, boxW, boxH);
    ctx.strokeRect(boxX, boxY, boxW, boxH);

    // Score Label
    ctx.fillStyle = '#9aa19c';
    ctx.font = 'bold 24px monospace';
    ctx.fillText('FINAL SCORE / 最終戰績', boxX + 40, boxY + 60);

    // Score Value
    ctx.fillStyle = '#18f2b2';
    ctx.shadowColor = '#18f2b2';
    ctx.shadowBlur = 20;
    ctx.font = '900 110px monospace';
    ctx.fillText(score.toLocaleString(), boxX + 40, boxY + 175);
    ctx.shadowBlur = 0;

    // Sub-stats: Length & Time
    const minutes = Math.floor(durationSeconds / 60);
    const seconds = durationSeconds % 60;
    const timeFormatted = `${minutes}:${seconds < 10 ? '0' : ''}${seconds}`;

    ctx.fillStyle = '#ffffff';
    ctx.font = 'bold 28px monospace';
    ctx.fillText(`LENGTH: ${length} BLOCKS`, boxX + 40, boxY + 250);
    ctx.fillText(`TIME ALIVE: ${timeFormatted}`, boxX + 40, boxY + 295);

    // 4. Footer & Link
    ctx.fillStyle = '#ffd700';
    ctx.font = 'bold 24px monospace';
    ctx.fillText('PLAY NOW: https://www.snek.com.tw/game/', 60, height - 55);

    return card;
  }

  public static shareToTwitter(score: number, length: number): void {
    const text = `SNEK Arcade 戰報：拿下 ${score} 分 (長度 ${length} 節)！\n你能超越這條巨蟒嗎？\n\n#SNEK #Cardano #SnekTaiwan $SNEK`;
    const url = 'https://www.snek.com.tw/game/';
    const twitterUrl = `https://twitter.com/intent/tweet?text=${encodeURIComponent(text)}&url=${encodeURIComponent(url)}`;
    window.open(twitterUrl, '_blank', 'noopener,noreferrer');
  }

  public static downloadCanvas(canvas: HTMLCanvasElement, filename = 'snek-arcade-score.png'): void {
    const a = document.createElement('a');
    a.href = canvas.toDataURL('image/png');
    a.download = filename;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
  }
}
